mapper.insert:

    SELECT LAST_INSERT_ID()

INSERT INTO recipients (
senior_id, bank_code, account_no, holder_name,
send_count, first_sent_at, last_sent_at,
is_registered_safe, safe_registered_by, safe_registered_at, account_alias
) VALUES (
#{wardId}, #{bankCode}, #{accountNo}, #{holderName},
0, NULL, NULL,
TRUE, #{guardId}, NOW(), #{accountAlias}
)

mapper.select:
SELECT EXISTS (
SELECT 1
FROM transactions t
JOIN wallets w ON t.wallet_id = w.wallet_id
WHERE w.user_id = #{wardId}
AND t.recipient_id = #{recipientId}
AND t.type = 'TRANSFER_OUT'
AND t.status = 'COMPLETED'
)

mapper.update:
UPDATE recipients
SET is_registered_safe = TRUE,
safe_registered_by = #{registeredBy},
safe_registered_at = NOW(),
account_alias = #{accountAlias}
WHERE recipient_id = #{recipientId}
